#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    int fd[2];
    if (pipe(fd) == -1) { perror("pipe"); exit(EXIT_FAILURE); }

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        close(fd[0]);
        int somme = 0;
        for (int i = 1; i <= 100; i++)
            somme += i;
        write(fd[1], &somme, sizeof(somme));
        close(fd[1]);
        exit(EXIT_SUCCESS);
    }

    close(fd[1]);
    int somme;
    read(fd[0], &somme, sizeof(somme));
    close(fd[0]);
    wait(NULL);
    printf("somme = %d\n", somme);
    return 0;
}

