#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>

struct message { long mtype; char texte[64]; };

int main(void) {
    int msqid = msgget(IPC_PRIVATE, IPC_CREAT | 0600);
    if (msqid == -1) { perror("msgget"); exit(EXIT_FAILURE); }

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        struct message m;
        m.mtype = 1;
        strcpy(m.texte, "coucou");
        if (msgsnd(msqid, &m, sizeof(m.texte), 0) == -1) {
            perror("msgsnd"); exit(EXIT_FAILURE);
        }
        exit(EXIT_SUCCESS);
    }

    struct message r;
    if (msgrcv(msqid, &r, sizeof(r.texte), 1, 0) == -1) {
        perror("msgrcv"); exit(EXIT_FAILURE);
    }
    printf("pere a recu : %s\n", r.texte);
    wait(NULL);
    msgctl(msqid, IPC_RMID, NULL);
    return 0;
}

