#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main(void) {
    int tube[2];
    if (pipe(tube) == -1) { perror("pipe"); exit(EXIT_FAILURE); }

    pid_t pid = fork();
    if (pid == -1) { perror("fork"); exit(EXIT_FAILURE); }

    if (pid == 0) {
        /* ===== SERVEUR ===== */
        close(tube[0]);
        int ecoute = socket(AF_INET, SOCK_STREAM, 0);
        if (ecoute == -1) { perror("socket"); exit(EXIT_FAILURE); }

        struct sockaddr_in adr;
        memset(&adr, 0, sizeof(adr));
        adr.sin_family = AF_INET;
        adr.sin_addr.s_addr = htonl(INADDR_ANY);
        adr.sin_port = htons(0);
        if (bind(ecoute, (struct sockaddr *) &adr, sizeof(adr)) == -1) {
            perror("bind"); exit(EXIT_FAILURE);
        }

        socklen_t lg = sizeof(adr);
        getsockname(ecoute, (struct sockaddr *) &adr, &lg);
        unsigned short port = ntohs(adr.sin_port);

        write(tube[1], &port, sizeof(port));
        close(tube[1]);

        struct sockaddr_in client;
        socklen_t lgc = sizeof(client);
        int service = accept(ecoute, (struct sockaddr *) &client, &lgc);
        if (service == -1) { perror("accept"); exit(EXIT_FAILURE); }

        /* BUG : listen est appele trop tard, apres accept */
        listen(ecoute, 5);

        char tampon[128];
        ssize_t n = recv(service, tampon, sizeof(tampon) - 1, 0);
        if (n > 0) {
            tampon[n] = '\0';
            const char *rep = "bonjour client";
            send(service, rep, strlen(rep), 0);
        }
        close(service);
        close(ecoute);
        exit(EXIT_SUCCESS);
    }

    /* ===== CLIENT ===== */
    close(tube[1]);
    unsigned short port;
    read(tube[0], &port, sizeof(port));
    close(tube[0]);

    int sk = socket(AF_INET, SOCK_STREAM, 0);
    if (sk == -1) { perror("socket"); exit(EXIT_FAILURE); }

    struct sockaddr_in serveur;
    memset(&serveur, 0, sizeof(serveur));
    serveur.sin_family = AF_INET;
    serveur.sin_port = htons(port);
    inet_aton("127.0.0.1", &serveur.sin_addr);

    if (connect(sk, (struct sockaddr *) &serveur, sizeof(serveur)) == -1) {
        perror("connect"); exit(EXIT_FAILURE);
    }

    const char *msg = "bonjour serveur";
    send(sk, msg, strlen(msg), 0);

    char tampon[128];
    ssize_t n = recv(sk, tampon, sizeof(tampon) - 1, 0);
    if (n > 0) {
        tampon[n] = '\0';
        printf("client a recu : %s\n", tampon);
    }
    close(sk);
    wait(NULL);
    return 0;
}

